import json,pathlib,collections,re,hashlib
from review_math import prompt,matrices,correct_index,check
E=pathlib.Path(__file__).resolve().parent

def load(p):return json.loads((E/p).read_text())
def save(p,v):(E/p).write_text(json.dumps(v,indent=2,default=str)+'\n')
def stats(rs):
 vals=collections.defaultdict(collections.Counter)
 for r in rs:
  m=prompt(r['question']).rref()[0]
  for name,v in zip(('sx','sy','bx','by'),[-m[0,2],-m[1,2],m[0,3],m[1,3]]):vals[name][int(v)]+=1
