sets={'fresh_raw':load('independent-samples.json'),'fresh_delivered':load('delivery-independent/accepted.json'),'batch_raw':load('runner-batch.json'),'batch_delivered':load('delivery-batch/accepted.json'),'supplemental_raw':load('supplemental-records.json'),'supplemental_delivered':load('delivery-supplemental/accepted.json')}
