 for subgroup,records,scope in groups:
  if not records:continue
  for cue in ('first authored option','shortest TeX','most minus signs','most zeros'):
   hits=0
   for r in records:
    vals=[a[':answer/value'] for a in r['question'][':question/answer-fields'][0][':answer-field/choices']]
    if cue=='first authored option':idx=0
    elif cue=='shortest TeX':idx=min(range(5),key=lambda j:len(vals[j]))
    elif cue=='most minus signs':idx=max(range(5),key=lambda j:vals[j].count('-'))
    else:idx=max(range(5),key=lambda j:sum(v==0 for v in matrices(vals[j])[0]))
    hits+=idx==correct_index(r['question'])
   probes.append({'cue':cue,'subgroup':n+':'+subgroup,'scope':scope,'strategy':'Choose '+cue+'; break ties by authored order.','correct':hits,'total':len(records),'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline 1/5 uniform choice. These finite subgroup rates are descriptive, not a statistical guarantee. Current code chooses the key before exchangeable candidate values; this cue has no fixed answer role. New profiles also challenged on eight fresh control seeds each; prior shortest-option concern replayed on ten controls. Small subgroups with one/two successes alone do not establish a construction shortcut.','sample_refs':['decision-probe-results.json',{'fresh_raw':'independent-samples.json','fresh_delivered':'delivery-independent/accepted.json','batch_raw':'runner-batch.json','batch_delivered':'delivery-batch/accepted.json','supplemental_delivered':'delivery-supplemental/accepted.json'}[n]]})
